<?php
declare(strict_types=1);
header('X-Robots-Tag: noindex, nofollow', true);
$configFile=__DIR__.'/catalog-config.php';
$config=is_file($configFile)?require $configFile:null;
function json_out($data,int $status=200):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function cfg_ready($c):bool{return is_array($c)&&!empty($c['supabase_url'])&&!empty($c['publishable_key'])&&!empty($c['admin_token']);}
function supa_rpc(array $c,string $fn,array $body):array{
  $ch=curl_init(rtrim($c['supabase_url'],'/').'/rest/v1/rpc/'.$fn);
  curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>12,CURLOPT_HTTPHEADER=>['apikey: '.$c['publishable_key'],'Content-Type: application/json','Accept: application/json'],CURLOPT_POSTFIELDS=>json_encode($body,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);
  $raw=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);
  if($raw===false||$err!=='')return ['ok'=>false,'status'=>502,'error'=>$err?:'Connessione Supabase non riuscita'];
  $decoded=json_decode($raw,true);if($code<200||$code>=300)return ['ok'=>false,'status'=>$code,'error'=>is_array($decoded)?($decoded['message']??'Errore Supabase'):$raw];
  return ['ok'=>true,'status'=>$code,'data'=>$decoded];
}
function sanitize_key(string $key):string{$key=trim($key);return preg_match('/^[^\s\x00-\x1F\/\\]{1,80}$/u',$key)?$key:'';}
function upload_logo(array $c):never{
  if(!isset($_FILES['logo'])||!is_uploaded_file($_FILES['logo']['tmp_name']))json_out(['ok'=>false,'error'=>'File logo mancante'],400);
  $key=sanitize_key((string)($_POST['brand_key']??''));if($key==='')json_out(['ok'=>false,'error'=>'Chiave brand non valida'],400);
  if((int)$_FILES['logo']['size']>5*1024*1024)json_out(['ok'=>false,'error'=>'Logo troppo grande: massimo 5 MB'],400);
  $finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($_FILES['logo']['tmp_name']);$ext=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'][$mime]??null;if(!$ext)json_out(['ok'=>false,'error'=>'Formato logo: PNG, JPG o WebP'],400);
  $publicPath=(string)($c['logo_public_path']??'/assets/catalog-brands');$disk=dirname(__DIR__).$publicPath;if(!is_dir($disk)&&!mkdir($disk,0775,true))json_out(['ok'=>false,'error'=>'Impossibile creare cartella loghi'],500);
  $safe=preg_replace('/[^a-z0-9_-]+/i','-',iconv('UTF-8','ASCII//TRANSLIT',$key)?:$key);$name=strtolower(trim($safe,'-')).'-'.substr(hash_file('sha256',$_FILES['logo']['tmp_name']),0,12).'.'.$ext;
  if(!move_uploaded_file($_FILES['logo']['tmp_name'],$disk.'/'.$name))json_out(['ok'=>false,'error'=>'Salvataggio logo non riuscito'],500);
  $scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$host=$_SERVER['HTTP_HOST']??'fi-card.app';
  json_out(['ok'=>true,'logo_url'=>$scheme.'://'.$host.rtrim($publicPath,'/').'/'.$name]);
}
if(isset($_GET['api'])){
  if(!cfg_ready($config))json_out(['ok'=>false,'error'=>'catalog-config.php non configurato'],503);
  $api=(string)$_GET['api'];
  if($api==='list'){$r=supa_rpc($config,'ficard_admin_catalog',['p_token'=>$config['admin_token']]);json_out($r['ok']?['ok'=>true,'brands'=>$r['data']]:['ok'=>false,'error'=>$r['error']],$r['ok']?200:$r['status']);}
  if($api==='save'&&$_SERVER['REQUEST_METHOD']==='POST'){$payload=json_decode(file_get_contents('php://input'),true);if(!is_array($payload))json_out(['ok'=>false,'error'=>'Payload non valido'],400);$r=supa_rpc($config,'ficard_admin_save_brand',['p_token'=>$config['admin_token'],'p_payload'=>$payload]);json_out($r['ok']?['ok'=>true,'brand'=>$r['data']]:['ok'=>false,'error'=>$r['error']],$r['ok']?200:$r['status']);}
  if($api==='upload'&&$_SERVER['REQUEST_METHOD']==='POST')upload_logo($config);
  json_out(['ok'=>false,'error'=>'Operazione non valida'],404);
}
$markets=is_array($config['implemented_markets']??null)?$config['implemented_markets']:['IT'=>'Italia'];
?><!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Fi-Card Developer · Catalogo</title><style>
:root{--v:#5B3DF5;--t:#2DD4BF;--bg:#f7f8fc;--s:#fff;--tx:#1f2937;--m:#6b7280;--l:#e5e7eb;--d:#dc2626}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--tx);font:14px Inter,system-ui,sans-serif}header{padding:22px 24px;background:#17152b;color:white;display:flex;justify-content:space-between;align-items:center}header b{font-size:20px}main{max-width:1320px;margin:22px auto;padding:0 18px;display:grid;grid-template-columns:minmax(320px,.85fr) minmax(420px,1.15fr);gap:18px}.box{background:var(--s);border:1px solid var(--l);border-radius:18px;padding:16px}.toolbar{display:flex;gap:8px;margin-bottom:12px}.toolbar input{flex:1}.field,input,select{width:100%;border:1px solid var(--l);border-radius:11px;padding:10px;background:#fff}label{display:block;color:var(--m);font-size:12px;font-weight:700;margin:12px 0 5px}.row{display:grid;grid-template-columns:1fr 1fr;gap:10px}.btn{border:0;border-radius:11px;padding:10px 13px;font-weight:800;cursor:pointer}.primary{background:var(--v);color:white}.secondary{background:#efecff;color:var(--v)}.danger{background:#fee2e2;color:#991b1b}.list{max-height:72vh;overflow:auto;border-top:1px solid var(--l)}.item{padding:11px 8px;border-bottom:1px solid var(--l);cursor:pointer;display:flex;justify-content:space-between;gap:10px}.item:hover{background:#fafaff}.item small{display:block;color:var(--m);margin-top:3px}.badge{font-size:10px;font-weight:900;border-radius:999px;padding:4px 7px;height:max-content;background:#eef2ff;color:#4338ca}.badge.pub{background:#dcfce7;color:#166534}.badge.off{background:#fee2e2;color:#991b1b}.badge.base{background:#fff7ed;color:#9a3412}.markets{display:flex;flex-wrap:wrap;gap:8px;margin-top:7px}.markets label{margin:0;border:1px solid var(--l);border-radius:999px;padding:7px 10px;color:var(--tx);font-weight:700}.markets input{width:auto;margin-right:5px}.status{min-height:20px;color:var(--m);margin:8px 0}.preview{border-radius:18px;min-height:115px;padding:18px;margin-top:12px;display:flex;align-items:center;justify-content:center;overflow:hidden}.preview img{max-width:80%;max-height:72px;object-fit:contain}.preview strong{font-size:24px}.note{background:#f3f4f6;border-radius:12px;padding:10px;color:#4b5563;font-size:12px;margin:10px 0}.configwarn{background:#fff7ed;color:#9a3412;padding:12px;border-radius:12px;margin-bottom:12px}@media(max-width:850px){main{grid-template-columns:1fr}.list{max-height:42vh}}
</style></head><body><header><div><b>Fi-Card Developer</b><div style="opacity:.7;font-size:12px">Catalogo brand remoto</div></div><button class="btn secondary" id="newBtn">＋ Nuovo brand</button></header><main>
<section class="box"><div class="toolbar"><input id="search" placeholder="Cerca brand, chiave, categoria…"><button class="btn secondary" id="reload">Aggiorna</button></div><div id="count" class="status"></div><div id="list" class="list"></div></section>
<section class="box"><?php if(!cfg_ready($config)):?><div class="configwarn">Manca <b>catalog-config.php</b>. Copia il file di esempio e inserisci il token amministrativo del catalogo.</div><?php endif;?>
<div id="legacyNote" class="note" hidden>Questa è ancora una scheda base incorporata nell’app. Salvandola qui, il catalogo server diventa autorevole per questo brand.</div>
<div class="row"><div><label>Chiave brand</label><input id="key" placeholder="es. conad"></div><div><label>Nome visualizzato</label><input id="name" placeholder="es. Conad"></div></div>
<div class="row"><div><label>Categoria</label><select id="category"><option value="supermercati">Supermercati</option><option value="abbigliamento">Abbigliamento</option><option value="sport">Sport</option><option value="elettronica">Elettronica</option><option value="casa">Casa / bricolage</option><option value="casalinghi">Casalinghi</option><option value="petstore">Pet store</option><option value="farmacia">Farmacia</option><option value="beauty">Beauty</option><option value="ristorazione">Ristorazione</option><option value="carburanti">Carburanti</option><option value="altro">Altro</option></select></div><div><label>Colore tessera</label><input id="color" type="color" value="#5B3DF5"></div></div>
<div class="row"><div><label>Sigla / fallback</label><input id="mark" placeholder="CONAD"></div><div><label>Dominio ufficiale</label><input id="domain" placeholder="conad.it"></div></div>
<label>Logo pubblico</label><div class="row"><input id="logo" placeholder="https://…"><input id="logoFile" type="file" accept="image/png,image/jpeg,image/webp"></div><button class="btn secondary" id="uploadBtn" type="button" style="margin-top:8px">Carica logo</button>
<label>Scala logo <span id="scaleOut">70%</span></label><input id="scale" type="range" min="10" max="100" value="70">
<div class="preview" id="preview"><strong>ANTEPRIMA</strong></div>
<label>Mercato</label><label style="display:flex;gap:8px;align-items:center;color:var(--tx);font-size:14px"><input id="international" type="checkbox" checked style="width:auto"> Internazionale</label><div class="markets" id="markets"><?php foreach($markets as $code=>$label):?><label><input type="checkbox" value="<?=htmlspecialchars($code)?>"> <?=htmlspecialchars($label)?> <small><?=htmlspecialchars($code)?></small></label><?php endforeach;?></div>
<div class="row"><div><label>Stato</label><select id="state"><option value="draft">Bozza</option><option value="published">Pubblicato</option><option value="disabled">Disattivato</option></select></div><div><label>Revisione</label><input id="revision" value="—" disabled></div></div>
<div id="msg" class="status"></div><button class="btn primary" id="saveBtn" style="width:100%">Salva scheda</button>
</section></main><script>
const els=id=>document.getElementById(id), marketChecks=[...document.querySelectorAll('#markets input')];let brands=[],editing=null;
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function badge(b){if(!b.is_complete)return '<span class="badge base">BASE APP</span>';if(b.status==='published')return '<span class="badge pub">PUBBLICATO</span>';if(b.status==='disabled')return '<span class="badge off">DISATTIVATO</span>';return '<span class="badge">BOZZA</span>'}
function renderList(){const q=els('search').value.trim().toLowerCase();const rows=brands.filter(b=>!q||[b.brand_key,b.name,b.category,(b.markets||[]).join(' ')].join(' ').toLowerCase().includes(q));els('count').textContent=rows.length+' schede';els('list').innerHTML=rows.map((b,i)=>'<div class="item" data-k="'+esc(b.brand_key)+'"><div><b>'+esc(b.is_complete?b.name:b.brand_key)+'</b><small>'+esc(b.brand_key)+' · '+esc(b.category)+(b.international?' · internazionale':' · '+esc((b.markets||[]).join(', ')))+'</small></div>'+badge(b)+'</div>').join('');document.querySelectorAll('.item').forEach(x=>x.onclick=()=>edit(x.dataset.k))}
function blank(){editing=null;els('key').disabled=false;els('key').value='';els('name').value='';els('category').value='altro';els('color').value='#5B3DF5';els('mark').value='';els('domain').value='';els('logo').value='';els('scale').value=70;els('state').value='draft';els('revision').value='—';els('international').checked=true;marketChecks.forEach(x=>x.checked=false);els('legacyNote').hidden=true;marketMode();preview()}
function edit(k){const b=brands.find(x=>x.brand_key===k);if(!b)return;editing=b;els('key').disabled=true;els('key').value=b.brand_key;els('name').value=b.is_complete?b.name:b.brand_key;els('category').value=b.category||'altro';els('color').value=b.color||'#5B3DF5';els('mark').value=b.mark||'';els('domain').value=b.domain||'';els('logo').value=b.logo_url||'';els('scale').value=b.logo_scale||70;els('state').value=b.status||'draft';els('revision').value=b.revision||1;els('international').checked=b.international!==false;marketChecks.forEach(x=>x.checked=(b.markets||[]).includes(x.value));els('legacyNote').hidden=!!b.is_complete;marketMode();preview();scrollTo({top:0,behavior:'smooth'})}
function marketMode(){const off=els('international').checked;marketChecks.forEach(x=>x.disabled=off)}
function preview(){const c=els('color').value||'#5B3DF5',url=els('logo').value.trim(),name=els('name').value||els('mark').value||'ANTEPRIMA';els('preview').style.background=c;els('scaleOut').textContent=els('scale').value+'%';els('preview').innerHTML=url?'<img style="width:'+els('scale').value+'%" src="'+esc(url)+'" onerror="this.replaceWith(document.createTextNode(\''+esc(name).replace(/'/g,'')+'\'))">':'<strong>'+esc(name)+'</strong>'}
async function load(){els('msg').textContent='Carico catalogo…';try{const r=await fetch('?api=list',{credentials:'same-origin',cache:'no-store'}),j=await r.json();if(!j.ok)throw new Error(j.error||'Errore');brands=Array.isArray(j.brands)?j.brands:[];renderList();els('msg').textContent=''}catch(e){els('msg').textContent=e.message}}
async function upload(){const f=els('logoFile').files[0],k=els('key').value.trim();if(!f||!k){els('msg').textContent='Inserisci la chiave brand e scegli un logo.';return}const fd=new FormData();fd.append('logo',f);fd.append('brand_key',k);els('msg').textContent='Carico logo…';try{const r=await fetch('?api=upload',{method:'POST',body:fd,credentials:'same-origin'}),j=await r.json();if(!j.ok)throw new Error(j.error||'Errore upload');els('logo').value=j.logo_url;preview();els('msg').textContent='Logo caricato.'}catch(e){els('msg').textContent=e.message}}
async function save(){const payload={brand_key:els('key').value.trim(),name:els('name').value.trim(),category:els('category').value,color:els('color').value,mark:els('mark').value.trim()||null,domain:els('domain').value.trim()||null,logo_url:els('logo').value.trim()||null,logo_bg:'transparent',logo_scale:Number(els('scale').value),international:els('international').checked,markets:marketChecks.filter(x=>x.checked).map(x=>x.value),status:els('state').value};if(!payload.brand_key||!payload.name){els('msg').textContent='Chiave e nome sono obbligatori.';return}if(!payload.international&&!payload.markets.length){els('msg').textContent='Se non è internazionale seleziona almeno un mercato.';return}els('msg').textContent='Salvo…';try{const r=await fetch('?api=save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),credentials:'same-origin'}),j=await r.json();if(!j.ok)throw new Error(j.error||'Errore salvataggio');els('msg').textContent='Salvato. Le app lo riceveranno al prossimo controllo catalogo.';await load();edit(payload.brand_key)}catch(e){els('msg').textContent=e.message}}
els('search').oninput=renderList;els('reload').onclick=load;els('newBtn').onclick=blank;els('international').onchange=marketMode;els('uploadBtn').onclick=upload;els('saveBtn').onclick=save;['name','mark','logo','color','scale'].forEach(id=>els(id).addEventListener('input',preview));blank();load();
</script></body></html>